import { dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { FlatCompat } from "@eslint/eslintrc";

// ESLint 9 flat config wrapping the legacy eslint-config-next presets.
// The project previously ran `next lint` with no ESLint installed at all
// (the script died on a missing binary); it now runs the ESLint CLI directly,
// which is the supported path for Next 15.
const compat = new FlatCompat({
  baseDirectory: dirname(fileURLToPath(import.meta.url)),
});

const eslintConfig = [
  {
    // next-env.d.ts is generated by `next build`; its triple-slash
    // references are Next's own convention and not ours to lint.
    ignores: [".next/**", "node_modules/**", "next-env.d.ts"],
  },
  ...compat.extends("next/core-web-vitals", "next/typescript"),
];

export default eslintConfig;
